/* Hash routes keep section pages and browser Back usable in the standalone file. */
let directoryCategory='all',directoryPage=1,vehicleDraft=[],vehicleBusy=false;const memberPageSize=6;
const directoryRoles={produce:'Farmer',buyers:'Wholesale buyer',transport:'Transport provider',supplies:'Fertilizer supplier',equipment:'Equipment seller',land:'Land seller',export:'Exporter'};
window.clearSection=()=>{directoryCategory='all';history.replaceState(null,'','#/');document.body.classList.remove('section-page');$('#directory-page').hidden=true;};
window.openSection=id=>{if(!categories.some(c=>c[0]===id))id='all';location.hash=id==='all'?'#/':`#/${id}`;applySectionRoute();};
function applySectionRoute(){const [route,query='']=location.hash.replace(/^#\//,'').split('?');const next=directoryRoles[route]?route:'all';const changed=directoryCategory!==next;directoryCategory=next;directoryPage=Math.max(1,Number.parseInt(new URLSearchParams(query).get('page')||'1',10)||1);category=directoryCategory;view='all';feedScope=directoryCategory==='all'?'recommended':'all';if(changed){$('#search').value='';$('#district').value='';$('#member-search').value='';$('#member-district').value='';$('#member-sort').value='new';}render();window.scrollTo?.({top:0,behavior:'smooth'});}
function setDirectoryPage(page){directoryPage=Math.max(1,page);history.pushState(null,'',`#/${directoryCategory}?page=${directoryPage}`);window.renderDirectory();}
function resetDirectoryPage(){directoryPage=1;history.replaceState(null,'',`#/${directoryCategory}?page=1`);window.renderDirectory();}

function directoryMembers(id,query='',district=''){return profiles.filter(p=>p.role===directoryRoles[id]&&(!district||p.district===district)&&[p.name,p.district,p.location,p.bio,p.vehicle,p.routes].filter(Boolean).join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));}
function latestTransportBid(id){return state.bids.filter(b=>b.profileId===id&&b.type==='transport').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];}
function detailFact(name,value){return `<p><strong>${name}</strong><br><span data-no-translate>${safe(value||'—')}</span></p>`;}
window.renderDirectory=()=>{const active=directoryCategory!=='all';document.body.classList.toggle('section-page',active);$('#directory-page').hidden=!active;if(!active)return;category=directoryCategory;$('#directory-title').textContent=label(directoryCategory);$('#edit-profile').hidden=!currentProfile();const members=memberSort(directoryMembers(directoryCategory,$('#member-search').value.trim(),$('#member-district').value),$('#member-sort').value,$('#member-price-basis').value||'kg');const pages=Math.max(1,Math.ceil(members.length/memberPageSize));const requestedPage=directoryPage;directoryPage=Math.min(directoryPage,pages);if(requestedPage!==directoryPage)history.replaceState(null,'',`#/${directoryCategory}?page=${directoryPage}`);$('#member-price-basis-label').hidden=directoryCategory!=='produce';$('#price-sort-note').hidden=directoryCategory!=='produce';$('#member-sort').querySelectorAll('option[value^="price-"]').forEach(option=>option.disabled=directoryCategory!=='produce');$('#member-count').textContent=`${members.length} registered members`;$('#member-range').textContent=members.length?`${(directoryPage-1)*memberPageSize+1}–${Math.min(directoryPage*memberPageSize,members.length)} / ${members.length}`:'';$('#member-pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button data-member-page="${i+1}" ${i+1===directoryPage?'aria-current="page"':''}>${i+1}</button>`).join(''):'';$('#member-empty').hidden=!!members.length;$('#member-grid').innerHTML=members.slice((directoryPage-1)*memberPageSize,directoryPage*memberPageSize).map(p=>{const transport=p.role==='Transport provider',bid=latestTransportBid(p.id);return `<article class="card member-card">${transport?`<div class="art" style="--art:#d8ddbf">${p.vehicleImages?.length?`<img class="listing-cover" src="${safe(p.vehicleImages[0])}" alt="${safe(p.vehicle||p.name)}">`:'<span>🚚</span>'}</div>`:''}<div class="card-body"><span class="badge">${safe(p.role)}</span><h3 data-no-translate>${safe(p.name)}</h3><p>${safe(p.district)}</p>${ratingHtml(p.id)}${directoryCategory==='produce'?`<p><strong>From</strong> <span data-no-translate>${memberPrice(p.id,$('#member-price-basis').value||'kg')!==null?'LKR '+memberPrice(p.id,$('#member-price-basis').value||'kg').toLocaleString('en-LK')+' / '+($('#member-price-basis').value||'kg'):''}</span>${memberPrice(p.id,$('#member-price-basis').value||'kg')===null?'Price not listed':''}</p>`:''}${p.location?`<p data-no-translate>${safe(p.location)}</p>`:''}${transport?`${detailFact('Vehicle type and capacity',p.vehicle)}${detailFact('Rates and pricing basis',p.rate)}<p><strong>Availability</strong><br>${safe(p.availability||'Not specified')}</p><p><strong>Latest transport bid</strong><br>${bid?`<span data-no-translate>LKR ${Number(bid.amount).toLocaleString('en-LK')}</span>`:'No transport bids yet'}</p>`:''}<button class="detail-button" data-member="${safe(p.id)}">View profile ↗</button></div></article>`}).join('');};
function showMember(id){const p=profiles.find(x=>x.id===id);if(!p)return;const bids=state.bids.filter(b=>b.profileId===p.id&&b.type==='transport').sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));$('#member-detail').innerHTML=`<p class="eyebrow">${safe(p.role)}</p><h2 data-no-translate>${safe(p.name)}</h2><p>${safe(p.district)}</p>${detailFact('Town / village / pickup location',p.location)}${detailFact('Description',p.bio)}${p.showPhone&&/^(?:0[0-9]{9}|\+94[0-9]{9})$/.test(p.phone)?`<p><strong>Contact phone number</strong><br><a data-no-translate href="tel:${safe(p.phone)}">${safe(p.phone)}</a></p>`:''}${p.role==='Transport provider'?`${p.vehicleImages?.length?`<div class="listing-gallery">${p.vehicleImages.map(image=>`<img src="${safe(image)}" alt="${safe(p.vehicle||p.name)}">`).join('')}</div>`:''}${detailFact('Vehicle type and capacity',p.vehicle)}${detailFact('Service areas / routes',p.routes)}${detailFact('Rates and pricing basis',p.rate)}<p><strong>Availability</strong><br>${safe(p.availability||'Not specified')}</p><h3>Transport bids</h3><p class="muted">Rates describe the service. Bids are quotes for a specific load and route.</p>${bids.length?bids.map(b=>`<article class="bid-row"><strong data-no-translate>${safe(all().find(x=>x.id===b.listingId)?.title||b.listingId)}</strong><b data-no-translate>LKR ${Number(b.amount).toLocaleString('en-LK')}</b><p data-no-translate>${safe(b.quantity)}</p><p data-no-translate>${safe(b.terms)}</p><button class="detail-button" data-bid-listing="${safe(b.listingId)}">View listing ↗</button></article>`).join(''):'<p>No transport bids yet</p>'}`:''}${customerReviewsHtml(p)}`;bindCustomerReviews(p);if(!$('#member-dialog').open)$('#member-dialog').showModal();}
function renderVehiclePreviews(){$('#vehicle-previews').innerHTML=vehicleDraft.map((src,i)=>`<div><img src="${safe(src)}" alt="${i+1}"><button type="button" data-remove-vehicle="${i}">Remove image</button></div>`).join('');}
function editBusinessProfile(){const p=currentProfile();if(!p)return;const form=$('#profile-form');for(const key of ['name','district','location','bio','vehicle','routes','rate','availability'])form.elements[key].value=p[key]||(key==='availability'?'Not specified':'');form.elements.showPhone.checked=!!p.showPhone;$('#vehicle-fields').hidden=p.role!=='Transport provider';vehicleDraft=[...(p.vehicleImages||[])];renderVehiclePreviews();$('#profile-dialog').showModal();}
function saveBusinessProfile(input){const p=currentProfile();if(!p)return false;if(!String(input.name||'').trim()||!districts.includes(input.district))return false;const next=profiles.map(item=>item.id!==p.id?item:{...item,name:String(input.name).trim(),district:input.district,location:String(input.location||'').trim(),bio:String(input.bio||'').trim(),showPhone:input.showPhone==='on',...(p.role==='Transport provider'?{vehicle:String(input.vehicle||'').trim(),routes:String(input.routes||'').trim(),rate:String(input.rate||'').trim(),availability:['Available','Unavailable','By arrangement'].includes(input.availability)?input.availability:'Not specified',vehicleImages:[...vehicleDraft]}:{})});try{localStorage.setItem('fd-profiles-v1',JSON.stringify(next));profiles=next;return true;}catch{toast('Browser storage is full or unavailable. This change could not be saved.');return false;}}
$('#profile-district').innerHTML=districts.map(option).join('');$('#member-district').insertAdjacentHTML('beforeend',districts.map(option).join(''));
$('#edit-profile').onclick=editBusinessProfile;
$('#profile-form').onsubmit=event=>{event.preventDefault();if(vehicleBusy){toast('Please wait for image processing.');return;}if(!event.target.reportValidity())return;if(saveBusinessProfile(Object.fromEntries(new FormData(event.target)))){$('#profile-dialog').close();render();toast('Business profile saved on this device.');}};
$('#vehicle-images').onchange=async event=>{if(vehicleBusy)return;const files=[...event.target.files];if(vehicleDraft.length+files.length>5){toast('You can add up to 5 images.');event.target.value='';return;}vehicleBusy=true;try{const added=[];for(const file of files)added.push(await compressListingImage(file));vehicleDraft.push(...added);renderVehiclePreviews();}catch(error){toast(error.message);}finally{vehicleBusy=false;event.target.value='';}};
$('#member-search').addEventListener('input',resetDirectoryPage);$('#member-district').addEventListener('change',resetDirectoryPage);$('#member-sort').addEventListener('change',resetDirectoryPage);$('#member-price-basis').addEventListener('change',resetDirectoryPage);
document.addEventListener('click',event=>{const page=event.target.closest('[data-member-page]');if(page)setDirectoryPage(Number(page.dataset.memberPage));const member=event.target.closest('[data-member]');if(member)showMember(member.dataset.member);const remove=event.target.closest('[data-remove-vehicle]');if(remove&&!vehicleBusy){vehicleDraft.splice(Number(remove.dataset.removeVehicle),1);renderVehiclePreviews();}const listing=event.target.closest('[data-bid-listing]');if(listing){$('#member-dialog').close();showDetail(listing.dataset.bidListing);}});
window.addEventListener('hashchange',applySectionRoute);applySectionRoute();

window.addEventListener('popstate',applySectionRoute);
